definition.script:
pipeline {
  agent any
  options { timestamps(); disableConcurrentBuilds(); buildDiscarder(logRotator(numToKeepStr: '20')) }
  stages {
    stage('CI + CD') {
      steps {
        sh '''
          set -euo pipefail
          export MODE="${MODE}"
          export OVERLAY="${OVERLAY}"
          export SOURCE="${SOURCE}"
          export IMAGE_TAG="${IMAGE_TAG}"
          export BRANCH_FREEDOM="${BRANCH_FREEDOM}"
          export BRANCH_WEB="${BRANCH_WEB}"
          export BRANCH_MALL="${BRANCH_MALL}"
          export GIT_SHA_FREEDOM="${GIT_SHA_FREEDOM:-}"
          export GIT_SHA_WEB="${GIT_SHA_WEB:-}"
          export GIT_SHA_MALL="${GIT_SHA_MALL:-}"
          export SKIP_MVN="$([ "${SKIP_MVN}" = "true" ] && echo 1 || echo 0)"
          export SKIP_FRONT="$([ "${SKIP_FRONT}" = "true" ] && echo 1 || echo 0)"
          export WORKSPACE_ROOT="${WORKSPACE}/repos"
          export JAVA_HOME=/opt/java/jdk-25
          export PATH="$JAVA_HOME/bin:/opt/maven/bin:/usr/local/bin:$PATH"
          if [[ -x /jenkins-backup/scripts/pipeline-wealth.sh ]]; then
            /jenkins-backup/scripts/pipeline-wealth.sh
          else
            chmod +x jenkins/scripts/pipeline-wealth.sh
            ./jenkins/scripts/pipeline-wealth.sh
          fi
        '''
      }
    }
  }
  post {
    always {
      script {
        def tagFile = "${env.WORKSPACE}/.wealth-image-tag"
        if (fileExists(tagFile)) {
          currentBuild.description = "MODE=${params.MODE} OVERLAY=${params.OVERLAY} IMAGE_TAG=${readFile(tagFile).trim()}"
        }
      }
    }
  }
}
